add_filter( 'woocommerce_catalog_orderby', 'perfectpixel_edit_sorting_options', 50 );

function perfectpixel_edit_sorting_options( $options ) {
	foreach ( array_filter( array_map( 'trim', explode( ',', '{{sorting_remove_keys}}' ) ) ) as $key ) {
		unset( $options[ $key ] );
	}
	foreach ( explode( '|', '{{sorting_renames}}' ) as $pair ) {
		$parts = array_map( 'trim', explode( '=', $pair, 2 ) );
		if ( 2 === count( $parts ) && isset( $options[ $parts[0] ] ) && '' !== $parts[1] ) {
			$options[ $parts[0] ] = $parts[1];
		}
	}
	return $options;
}
